    "home_d5_a": "Royal Den Capital exerce ses activités sous le permis de courtier hypothécaire n° M25002134 et le permis Mortgage Alliance Ontario n° 10530. Royal Den Capital est une entreprise détenue et exploitée de façon indépendante.",
    "home_d6_q": "Ne constitue pas un conseil financier, juridique ou fiscal",
