    "footer_intro_home": "Royal Den Capital ਵਪਾਰਾਂ ਨੂੰ ਵਿਕਾਸ, ਵਿਸਥਾਰ ਅਤੇ ਨਵੀਨਤਾ ਲਈ ਲੋੜੀਂਦੀ ਫੰਡਿੰਗ ਪ੍ਰਾਪਤ ਕਰਨ ਵਿੱਚ ਮਦਦ ਕਰਨ ਵਿੱਚ ਮਾਹਿਰ ਹੈ।",
    "footer_intro_generic": "Royal Den Capital ਗਾਹਕਾਂ ਨੂੰ ਘਰਾਂ, ਵਪਾਰਾਂ, ਨਿਵੇਸ਼ਾਂ ਅਤੇ ਭਵਿੱਖ ਦੇ ਵਾਧੇ ਲਈ ਫੰਡਿੰਗ ਪ੍ਰਾਪਤ ਕਰਨ ਵਿੱਚ ਮਦਦ ਕਰਨ ਵਿੱਚ ਮਾਹਿਰ ਹੈ।",
    "footer_copyright": "ਕਾਪੀਰਾਈਟ (c) 2026 | Royal Den Capital। ਸਾਰੇ ਅਧਿਕਾਰ ਰਾਖਵੇਂ ਹਨ।",
