    "mmr_cta_h2": "ਅਗਲੇ ਕੁਝ ਮਹੀਨਿਆਂ ਵਿੱਚ ਨਵਿਆ ਰਹੇ ਹੋ?",
    "mmr_cta_p": "ਸਾਨੂੰ ਆਪਣੀ ਨਵਿਆਉਣ ਦੀ ਪੇਸ਼ਕਸ਼ ਭੇਜੋ ਅਤੇ ਅਸੀਂ ਤੁਹਾਨੂੰ ਇਹ ਸਮਝਣ ਵਿੱਚ ਮਦਦ ਕਰਾਂਗੇ ਕਿ ਕੀ ਕੋਈ ਬਿਹਤਰ ਰਸਤਾ ਹੈ।",
