    "gl_start_h2": "ਮੌਰਗੇਜ ਅਸਲ ਵਿੱਚ ਕੀ ਹੈ",
    "gl_start_p1": "ਇੱਕ ਮੌਰਗੇਜ ਰੀਅਲ ਅਸਟੇਟ ਦੁਆਰਾ ਸੁਰੱਖਿਅਤ ਇੱਕ ਲੋਨ ਹੈ। ਤੁਸੀਂ ਜਾਇਦਾਦ ਖਰੀਦਣ, ਰੀਫਾਈਨੈਂਸ ਕਰਨ, ਜਾਂ ਇਕੁਇਟੀ ਤੱਕ ਪਹੁੰਚ ਕਰਨ ਲਈ ਪੈਸੇ ਉਧਾਰ ਲੈਂਦੇ ਹੋ, ਅਤੇ ਰਿਣਦਾਤਾ ਉਸ ਜਾਇਦਾਦ ਦੇ ਵਿਰੁੱਧ ਇੱਕ ਕਾਨੂੰਨੀ ਚਾਰਜ ਰਜਿਸਟਰ ਕਰਦਾ ਹੈ ਜਦੋਂ ਤੱਕ ਲੋਨ ਭੁਗਤਾਨ, ਟ੍ਰਾਂਸਫਰ, ਡਿਸਚਾਰਜ, ਜਾਂ ਬਦਲਿਆ ਨਹੀਂ ਜਾਂਦਾ।",
    "gl_start_p2": "ਜ਼ਿਆਦਾਤਰ ਗਾਹਕ ਪਹਿਲਾਂ ਵਿਆਜ ਦਰ 'ਤੇ ਧਿਆਨ ਦਿੰਦੇ ਹਨ। ਬਿਹਤਰ ਸ਼ੁਰੂਆਤੀ ਬਿੰਦੂ ਪੂਰਾ ਢਾਂਚਾ ਹੈ: ਲੋਨ ਰਕਮ, ਡਾਊਨ ਪੇਮੈਂਟ, ਅਮੌਰਟਾਈਜ਼ੇਸ਼ਨ, ਮਿਆਦ, ਭੁਗਤਾਨ ਬਾਰੰਬਾਰਤਾ, ਪ੍ਰੀਪੇਮੈਂਟ ਲਚਕਤਾ, ਜੁਰਮਾਨੇ, ਰਿਣਦਾਤਾ ਸ਼ਰਤਾਂ, ਕਲੋਜ਼ਿੰਗ ਲਾਗਤਾਂ, ਅਤੇ ਨਵਿਆਉਣ ਦੀ ਯੋਜਨਾ।",
    "gl_flow_1_t": "ਬਜਟ",
    "gl_flow_1_d": "ਆਮਦਨ, ਕਰਜ਼ੇ, ਡਾਊਨ ਪੇਮੈਂਟ, ਆਰਾਮ ਪੱਧਰ",
