    "gt_titleins_dd": "ਬੀਮਾ ਜੋ ਕੁਝ ਟਾਈਟਲ ਅਤੇ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਸਮੱਸਿਆਵਾਂ ਤੋਂ ਬਚਾਉਂਦਾ ਹੈ।",
