    "au_l2_p": "ਉੱਨਤ ਦ੍ਰਿਸ਼, ਰਿਣਦਾਤਾ ਗੱਲਬਾਤ, ਰੀਫਾਈਨੈਂਸ ਰਣਨੀਤੀ, ਕਮਰਸ਼ੀਅਲ ਗੱਲਬਾਤ, ਅਤੇ ਗੁੰਝਲਦਾਰ ਮਨਜ਼ੂਰੀ ਰਸਤਿਆਂ ਨੂੰ ਸੰਭਾਲਦੇ ਹਨ।",
