    "au_l1_p": "ਗਾਹਕ ਦਾਖਲੇ ਦੀ ਅਗਵਾਈ ਕਰਦੇ ਹਨ, ਦਸਤਾਵੇਜ਼ ਇਕੱਠੇ ਕਰਦੇ ਹਨ, ਅਰਜ਼ੀਆਂ ਤਿਆਰ ਕਰਦੇ ਹਨ, ਅਗਲੇ ਕਦਮ ਸਮਝਾਉਂਦੇ ਹਨ, ਅਤੇ ਸੰਚਾਰ ਜਾਰੀ ਰੱਖਦੇ ਹਨ।",
