    "au_uw_license": "ਅੰਦਰੂਨੀ ਫਾਈਲ ਸਹਾਇਤਾ",
    "au_uw_p": "ਦਸਤਾਵੇਜ਼ਾਂ ਦੀ ਸਮੀਖਿਆ ਕਰਦਾ ਹੈ, ਰਿਣਦਾਤਾ ਸ਼ਰਤਾਂ ਦੀ ਜਾਂਚ ਕਰਦਾ ਹੈ, ਜਮ੍ਹਾਂ ਕਰਾਉਣ ਨੂੰ ਸੰਗਠਿਤ ਕਰਦਾ ਹੈ, ਅਤੇ ਮਨਜ਼ੂਰੀ ਤੋਂ ਪਹਿਲਾਂ ਹਰ ਫਾਈਲ ਨੂੰ ਸਾਫ਼ ਬਣਾਉਣ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ।",
