    "au_why_kicker": "Royal Den Capital ਕਿਉਂ?",
    "au_why_h2": "25+ ਸਾਲਾਂ ਦੀ ਮੌਰਗੇਜ ਤਾਕਤ, ਰਿਣਦਾਤਾ ਪਹੁੰਚ, ਅਤੇ ਗਾਹਕ-ਪਹਿਲਾਂ ਸਲਾਹ।",
    "au_why_p": "Royal Den Capital ਉਹਨਾਂ ਗਾਹਕਾਂ ਲਈ ਬਣਾਇਆ ਗਿਆ ਹੈ ਜੋ ਇੱਕ ਤੇਜ਼ ਕੋਟ ਤੋਂ ਵੱਧ ਚਾਹੁੰਦੇ ਹਨ। ਅਸੀਂ ਤੁਹਾਨੂੰ ਭਰੋਸੇ ਨਾਲ ਅੱਗੇ ਵਧਣ ਵਿੱਚ ਮਦਦ ਕਰਨ ਲਈ ਤਜਰਬੇ, ਰਿਣਦਾਤਾ ਰਿਸ਼ਤਿਆਂ, ਤਿੱਖੀ ਦਰ ਤੁਲਨਾ, ਅਤੇ ਵਿਹਾਰਕ ਮਾਰਗਦਰਸ਼ਨ ਨੂੰ ਜੋੜਦੇ ਹਾਂ।",
    "au_w1_h3": "ਵਪਾਰ ਵਿੱਚ 25+ ਸਾਲ",
    "au_w1_p": "ਤਜਰਬਾ ਉਦੋਂ ਮਾਇਨੇ ਰੱਖਦਾ ਹੈ ਜਦੋਂ ਫਾਈਲ ਸਧਾਰਨ ਹੁੰਦੀ ਹੈ, ਅਤੇ ਇਹ ਹੋਰ ਵੀ ਵੱਧ ਮਾਇਨੇ ਰੱਖਦਾ ਹੈ ਜਦੋਂ ਇਹ ਨਹੀਂ ਹੁੰਦੀ। ਸਾਡੀ ਟੀਮ ਗਾਹਕਾਂ ਨੂੰ ਅੰਦਾਜ਼ੇ ਤੋਂ ਬਚਣ ਅਤੇ ਸਪਸ਼ਟਤਾ ਨਾਲ ਵਿੱਤ ਰਾਹੀਂ ਅੱਗੇ ਵਧਣ ਵਿੱਚ ਮਦਦ ਕਰਨ ਲਈ 25 ਸਾਲਾਂ ਤੋਂ ਵੱਧ ਮਾਰਕੀਟ ਗਿਆਨ ਲਿਆਉਂਦੀ ਹੈ।",
    "au_w1_li1": "ਅਸਲੀ ਮਾਰਕੀਟ ਚੱਕਰਾਂ ਦੁਆਰਾ ਆਕਾਰ ਦਿੱਤਾ ਮਾਰਗਦਰਸ਼ਨ, ਆਮ ਸਕ੍ਰਿਪਟਾਂ ਨਹੀਂ।",
    "au_w1_li2": "ਖਰੀਦਾਂ, ਨਵਿਆਉਣ, ਰੀਫਾਈਨੈਂਸ, ਅਤੇ ਗੁੰਝਲਦਾਰ ਫਾਈਲਾਂ ਲਈ ਵਿਹਾਰਕ ਸਲਾਹ।",
    "au_w2_h3": "ਹੋਰ ਰਿਣਦਾਤਿਆਂ ਤੱਕ ਪਹੁੰਚ",
    "au_w2_p": "ਇੱਕ ਰਿਣਦਾਤਾ ਸਿਰਫ਼ ਇੱਕ ਲੇਨ ਵਿਖਾ ਸਕਦਾ ਹੈ। Royal Den Capital ਗਾਹਕਾਂ ਨੂੰ ਬੈਂਕਾਂ, ਕ੍ਰੈਡਿਟ ਯੂਨੀਅਨਾਂ, ਮੋਨੋਲਾਈਨ ਰਿਣਦਾਤਿਆਂ, ਵਿਕਲਪਕ ਰਿਣਦਾਤਿਆਂ, ਅਤੇ ਪ੍ਰਾਈਵੇਟ ਵਿਕਲਪਾਂ ਦੇ ਇੱਕ ਵਿਸ਼ਾਲ ਨੈੱਟਵਰਕ ਤੱਕ ਪਹੁੰਚ ਦਿੰਦਾ ਹੈ ਤਾਂ ਜੋ ਫਾਈਲ ਕੋਲ ਕੰਮ ਕਰਨ ਦੇ ਵਧੇਰੇ ਤਰੀਕੇ ਹੋਣ।",
    "au_w2_li1": "ਹੋਰ ਰਿਣਦਾਤਾ ਰਸਤਿਆਂ ਦਾ ਮਤਲਬ ਹੈ ਗਾਹਕ ਦੀ ਅਸਲ ਸਥਿਤੀ ਨਾਲ ਮੇਲ ਕਰਨ ਦੇ ਵਧੇਰੇ ਮੌਕੇ।",
    "au_w2_li2": "ਮਜ਼ਬੂਤ ਬੈਂਕਯੋਗ ਫਾਈਲਾਂ ਅਤੇ ਰਚਨਾਤਮਕ ਢਾਂਚੇ ਦੀ ਲੋੜ ਵਾਲੀਆਂ ਫਾਈਲਾਂ ਲਈ ਲਾਭਦਾਇਕ।",
    "au_w3_h3": "ਬਿਹਤਰ ਦਰ ਖਰੀਦਦਾਰੀ",
    "au_w3_p": "ਅਸੀਂ ਤੁਹਾਡੀ ਪੂਰੀ ਸਥਿਤੀ ਨੂੰ ਧਿਆਨ ਵਿੱਚ ਰੱਖਦੇ ਹੋਏ ਰਿਣਦਾਤਾ ਵਿਕਲਪਾਂ ਦੀ ਤੁਲਨਾ ਕਰਦੇ ਹਾਂ, ਸਿਰਫ਼ ਸਕਰੀਨ 'ਤੇ ਸਭ ਤੋਂ ਘੱਟ ਅੰਕੜੇ ਦੀ ਨਹੀਂ। ਟੀਚਾ ਇੱਕ ਮਜ਼ਬੂਤ ਦਰ, ਨਿਰਪੱਖ ਸ਼ਰਤਾਂ, ਸੰਭਾਲਣਯੋਗ ਭੁਗਤਾਨ, ਅਤੇ ਬਾਰੀਕ ਪ੍ਰਿੰਟ ਵਿੱਚ ਲੁਕੀ ਕੋਈ ਹੈਰਾਨੀ ਨਹੀਂ ਹੈ।",
    "au_w3_li1": "ਦਰਾਂ ਦੀ ਤੁਲਨਾ ਜੁਰਮਾਨਿਆਂ, ਵਿਸ਼ੇਸ਼ ਅਧਿਕਾਰਾਂ, ਫੀਸਾਂ, ਅਤੇ ਲਚਕਤਾ ਦੇ ਨਾਲ ਕੀਤੀ ਜਾਂਦੀ ਹੈ।",
    "au_w3_li2": "ਗਾਹਕ ਵਚਨਬੱਧ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਸਮਝੌਤੇ ਵੇਖਦੇ ਹਨ।",
    "au_w4_h3": "ਤੁਹਾਡੇ ਆਲੇ-ਦੁਆਲੇ ਬਣੀ ਸਲਾਹ",
    "au_w4_p": "ਤੁਸੀਂ ਸਿਰਫ਼ ਇੱਕ ਹੋਰ ਅਰਜ਼ੀ ਨਹੀਂ ਹੋ। ਅਸੀਂ ਤੁਹਾਡੀ ਕਹਾਣੀ, ਤੁਹਾਡੀ ਸਮਾਂ-ਸੀਮਾ, ਤੁਹਾਡੀ ਆਮਦਨ, ਤੁਹਾਡੀ ਜਾਇਦਾਦ, ਅਤੇ ਤੁਹਾਡੇ ਲੰਬੇ ਸਮੇਂ ਦੇ ਟੀਚਿਆਂ ਨੂੰ ਸੁਣਦੇ ਹਾਂ, ਫਿਰ ਇੱਕ ਮੌਰਗੇਜ ਰਣਨੀਤੀ ਬਣਾਉਂਦੇ ਹਾਂ ਜੋ ਤੁਹਾਡੇ ਅਸਲ ਰਹਿਣ-ਸਹਿਣ ਅਤੇ ਕੰਮ ਕਰਨ ਦੇ ਤਰੀਕੇ ਦੇ ਅਨੁਕੂਲ ਹੋਵੇ।",
    "au_w4_li1": "ਹਰ ਸਿਫ਼ਾਰਸ਼ ਗਾਹਕ ਦੇ ਟੀਚਿਆਂ ਅਤੇ ਆਰਾਮ ਪੱਧਰ ਨਾਲ ਸ਼ੁਰੂ ਹੁੰਦੀ ਹੈ।",
    "au_w4_li2": "ਅਸੀਂ ਯੋਜਨਾ ਨੂੰ ਸਾਦੀ ਭਾਸ਼ਾ ਵਿੱਚ ਸਮਝਾਉਂਦੇ ਹਾਂ, ਰਿਣਦਾਤਾ ਸ਼ਬਦਜਾਲ ਵਿੱਚ ਨਹੀਂ।",
    "au_w5_h3": "ਗੁੰਝਲਦਾਰ ਫਾਈਲਾਂ ਲਈ ਹੱਲ",
    "au_w5_p": "ਸਵੈ-ਰੁਜ਼ਗਾਰ ਆਮਦਨ, ਕ੍ਰੈਡਿਟ ਚੁਣੌਤੀਆਂ, ਨਿਵੇਸ਼ ਜਾਇਦਾਦ, ਉਸਾਰੀ, ਕਮਰਸ਼ੀਅਲ ਵਿੱਤ, ਰੀਫਾਈਨੈਂਸਿੰਗ, ਜਾਂ ਕਰਜ਼ਾ ਇਕਸਾਰੀਕਰਨ ਸਭ ਨੂੰ ਸਮਾਰਟ ਢਾਂਚੇ ਦੀ ਲੋੜ ਹੁੰਦੀ ਹੈ। ਅਸੀਂ ਜਾਣਦੇ ਹਾਂ ਕਿ ਫਾਈਲ ਨੂੰ ਕਿਵੇਂ ਸਥਾਪਤ ਕਰਨਾ ਹੈ ਅਤੇ ਸਹੀ ਰਿਣ ਰਸਤਾ ਕਿਵੇਂ ਲੱਭਣਾ ਹੈ।",
    "au_w5_li1": "ਗੈਰ-ਮਿਆਰੀ ਆਮਦਨ ਅਤੇ ਵਿਲੱਖਣ ਜਾਇਦਾਦ ਦ੍ਰਿਸ਼ਾਂ ਲਈ ਮਜ਼ਬੂਤ ਸਹਾਇਤਾ।",
    "au_w5_li2": "ਫਾਈਲ ਦੇ ਅੰਡਰਰਾਈਟਿੰਗ ਤੱਕ ਪਹੁੰਚਣ ਤੋਂ ਪਹਿਲਾਂ ਸਪਸ਼ਟ ਸਥਿਤੀ।",
    "au_w6_h3": "ਹਰ ਮੌਰਗੇਜ ਲੋੜ ਲਈ ਇੱਕ ਥਾਂ",
    "au_w6_p": "ਖਰੀਦ, ਨਵਿਆਉਣ, ਰੀਫਾਈਨੈਂਸ, HELOC, ਇਕੁਇਟੀ ਟੇਕਆਊਟ, ਰੀਨੋਵੇਸ਼ਨ ਫੰਡਿੰਗ, ਨਿਊਕਮਰ ਪ੍ਰੋਗਰਾਮ, ਰਿਵਰਸ ਮੌਰਗੇਜ, ਅਤੇ ਕਮਰਸ਼ੀਅਲ ਮੌਰਗੇਜ ਸਭ ਇੱਕ ਛੱਤ ਹੇਠ ਇੱਕ ਜਵਾਬਦੇਹ ਟੀਮ ਨਾਲ ਸੰਭਾਲੇ ਜਾ ਸਕਦੇ ਹਨ।",
    "au_w6_li1": "ਮੌਰਗੇਜ ਯੋਜਨਾਬੰਦੀ, ਰਿਣਦਾਤਾ ਤੁਲਨਾ, ਅਤੇ ਅਗਲੇ ਕਦਮ ਮਾਰਗਦਰਸ਼ਨ ਲਈ ਇੱਕ ਥਾਂ।",
    "au_w6_li2": "ਘੱਟ ਉਲਝਣ, ਘੱਟ ਹੈਂਡਆਫ, ਅਤੇ ਇੱਕ ਸਾਫ਼ ਗਾਹਕ ਅਨੁਭਵ।",
    "au_cta_h2": "ਭਰੋਸੇ ਨਾਲ ਵਧਣ ਲਈ ਤਿਆਰ ਹੋ?",
    "au_cta_p": "Royal Den Capital ਵਿੱਚ, ਅਸੀਂ ਹਰ ਕਦਮ 'ਤੇ ਤੁਹਾਡੇ ਨਾਲ ਹਾਂ। ਖੋਜੋ ਕਿ ਇੱਕ ਟੀਮ ਹੋਣ ਦਾ ਕੀ ਮਤਲਬ ਹੈ ਜੋ ਸੱਚਮੁੱਚ ਪਰਵਾਹ ਕਰਦੀ ਹੈ, ਅਤੇ ਅਸਲ ਨਤੀਜੇ ਦੇਣ ਦੀ ਮੁਹਾਰਤ ਰੱਖਦੀ ਹੈ।",
    "au_cta_btn": "ਹੋਰ ਖੋਜੋ",
