    "au_card_h2": "ਆਓ ਮਿਲ ਕੇ ਤੁਹਾਡਾ ਭਵਿੱਖ ਬਣਾਈਏ।",
    "au_card_p": "ਭਾਵੇਂ ਤੁਸੀਂ ਖਰੀਦ ਰਹੇ ਹੋ, ਨਿਵੇਸ਼ ਕਰ ਰਹੇ ਹੋ, ਰੀਫਾਈਨੈਂਸ ਕਰ ਰਹੇ ਹੋ, ਜਾਂ ਵਿਕਾਸ ਕਰ ਰਹੇ ਹੋ, ਅਸੀਂ ਤੁਹਾਨੂੰ ਸਪਸ਼ਟਤਾ ਅਤੇ ਭਰੋਸੇ ਨਾਲ ਮਾਰਗਦਰਸ਼ਨ ਕਰਨ ਲਈ ਇੱਥੇ ਹਾਂ।",
    "au_mission_strong": "ਸਾਡਾ ਮਿਸ਼ਨ:",
    "au_mission_rest": " ਕੈਨੇਡੀਅਨਾਂ ਨੂੰ ਸਮਾਰਟ ਮੌਰਗੇਜ ਰਣਨੀਤੀਆਂ ਨਾਲ ਸਸ਼ਕਤ ਕਰਨਾ ਜੋ ਇੱਕ ਸਮੇਂ ਵਿੱਚ ਇੱਕ ਜਾਇਦਾਦ, ਸਥਿਰਤਾ, ਦੌਲਤ, ਅਤੇ ਲੰਬੇ ਸਮੇਂ ਦੀ ਸਫਲਤਾ ਬਣਾਉਂਦੀ ਹੈ।",
