    "cr_h1": "ਸਾਡੇ ਨਾਲ ਆਪਣਾ ਮੌਰਗੇਜ ਕਰੀਅਰ ਬਣਾਓ।",
    "cr_lead": "ਅਸੀਂ ਮਿਹਨਤੀ ਮੌਰਗੇਜ ਪੇਸ਼ੇਵਰਾਂ ਦੀ ਭਾਲ ਕਰ ਰਹੇ ਹਾਂ ਜੋ ਹੋਰ ਰਿਣਦਾਤਿਆਂ ਤੱਕ ਪਹੁੰਚ, ਮਜ਼ਬੂਤ ਮਾਰਗਦਰਸ਼ਨ, ਅਤੇ ਵਧਣ ਦੀ ਥਾਂ ਵਾਲਾ ਕਮਿਸ਼ਨ-ਆਧਾਰਿਤ ਮੌਕਾ ਚਾਹੁੰਦੇ ਹਨ।",
    "cr_fact1": "Oakville ਦਫ਼ਤਰ",
