    "cr_apply_now": "ਹੁਣੇ ਅਪਲਾਈ ਕਰੋ",
    "cr_view_role": "ਭੂਮਿਕਾ ਵੇਖੋ",
    "cr_who_h2": "ਇੱਥੇ ਕੌਣ ਫਿੱਟ ਹੁੰਦਾ ਹੈ?",
    "cr_who_li1": "ਲਾਇਸੰਸਸ਼ੁਦਾ ਜਾਂ ਇੱਛੁਕ ਮੌਰਗੇਜ ਏਜੰਟ।",
    "cr_who_li2": "ਸਵੈ-ਪ੍ਰੇਰਿਤ ਲੋਕ ਜੋ ਰਿਸ਼ਤੇ ਬਣਾ ਸਕਦੇ ਹਨ।",
    "cr_who_li3": "ਪੇਸ਼ੇਵਰ ਜੋ ਕਮਿਸ਼ਨ ਲਾਭ ਚਾਹੁੰਦੇ ਹਨ, ਨਾ ਕਿ ਇੱਕ ਫਿਕਸਡ ਤਨਖਾਹ ਰਸਤਾ।",
    "cr_who_li4": "ਏਜੰਟ ਜੋ ਢਾਂਚੇ, ਰਿਣਦਾਤਾ ਪਹੁੰਚ, ਅਤੇ ਫਾਈਲ ਸਹਾਇਤਾ ਦੀ ਕਦਰ ਕਰਦੇ ਹਨ।",
    "cr_why_kicker": "RDC ਵਿੱਚ ਕਿਉਂ ਸ਼ਾਮਲ ਹੋਈਏ",
    "cr_why_h2": "ਬੰਦ ਕਰਨ ਵਾਲਿਆਂ ਲਈ ਬਣਿਆ ਇੱਕ ਬ੍ਰੋਕਰੇਜ ਮਾਹੌਲ।",
    "cr_why_p": "ਅਸੀਂ ਵਾਅਦਾ ਸਧਾਰਨ ਰੱਖਦੇ ਹਾਂ: ਸਪਸ਼ਟ ਸਹਾਇਤਾ, ਗੰਭੀਰ ਰਿਣਦਾਤਾ ਵਿਕਲਪ, ਵਿਹਾਰਕ ਸਲਾਹ, ਅਤੇ ਇੱਕ ਟੀਮ ਜੋ ਚਾਹੁੰਦੀ ਹੈ ਕਿ ਹਰ ਫਾਈਲ ਸਹੀ ਢੰਗ ਨਾਲ ਸਥਾਪਤ ਹੋਵੇ।",
    "cr_b1_h3": "ਹੋਰ ਰਿਣਦਾਤਾ ਰਸਤੇ",
    "cr_b1_p": "ਗਾਹਕ ਸਾਰੇ ਇੱਕੋ ਬਾਕਸ ਵਿੱਚ ਫਿੱਟ ਨਹੀਂ ਹੁੰਦੇ। ਤੁਸੀਂ ਇੱਕ ਵਿਸ਼ਾਲ ਰਿਣ ਨੈੱਟਵਰਕ ਨਾਲ ਕੰਮ ਕਰੋਗੇ ਤਾਂ ਜੋ ਖਰੀਦ, ਰੀਫਾਈਨੈਂਸ, ਨਵਿਆਉਣ, ਇਕੁਇਟੀ, ਅਤੇ ਗੁੰਝਲਦਾਰ ਫਾਈਲਾਂ ਕੋਲ ਵਧੇਰੇ ਸੰਭਵ ਰਸਤੇ ਹੋਣ।",
    "cr_b2_h3": "ਕਮਿਸ਼ਨ-ਆਧਾਰਿਤ ਕਮਾਈ ਸੰਭਾਵਨਾ",
    "cr_b2_p": "ਇਹ ਇੱਕ ਕਮਿਸ਼ਨ-ਆਧਾਰਿਤ ਮੌਕਾ ਹੈ ਉਹਨਾਂ ਲੋਕਾਂ ਲਈ ਜੋ ਚਾਹੁੰਦੇ ਹਨ ਕਿ ਉਹਨਾਂ ਦੀ ਆਮਦਨ ਉਤਪਾਦਨ, ਰਿਸ਼ਤਾ ਬਣਾਉਣ, ਅਤੇ ਗਾਹਕ ਸੇਵਾ ਨਾਲ ਜੁੜੀ ਹੋਵੇ।",
    "cr_b3_h3": "ਤਜਰਬੇਕਾਰ ਲੀਡਰਸ਼ਿਪ ਤੋਂ ਮਾਰਗਦਰਸ਼ਨ",
    "cr_b3_p": "ਬ੍ਰਾਂਡ ਦੇ ਪਿੱਛੇ 25 ਸਾਲਾਂ ਤੋਂ ਵੱਧ ਮੌਰਗੇਜ ਅਤੇ ਲੋਨ ਦੇ ਤਜਰਬੇ ਨਾਲ, ਏਜੰਟ ਸਿੱਖ ਸਕਦੇ ਹਨ ਕਿ ਫਾਈਲਾਂ ਨੂੰ ਕਿਵੇਂ ਢਾਂਚਾ ਬਣਾਉਣਾ ਹੈ, ਬਿਹਤਰ ਸਵਾਲ ਕਿਵੇਂ ਪੁੱਛਣੇ ਹਨ, ਅਤੇ ਆਮ ਮਨਜ਼ੂਰੀ ਗਲਤੀਆਂ ਤੋਂ ਕਿਵੇਂ ਬਚਣਾ ਹੈ।",
    "cr_b4_h3": "Oakville ਟੀਮ ਮੌਜੂਦਗੀ",
    "cr_b4_p": "Royal Den Capital Oakville ਤੋਂ ਕੰਮ ਕਰਦਾ ਹੈ, ਏਜੰਟਾਂ ਨੂੰ ਸਹਿਯੋਗ, ਗਾਹਕ ਗੱਲਬਾਤ, ਅਤੇ ਫਾਈਲ ਸਹਾਇਤਾ ਲਈ ਇੱਕ ਪੇਸ਼ੇਵਰ ਆਧਾਰ ਦਿੰਦਾ ਹੈ।",
    "cr_gallery_cap1": "ਗੰਭੀਰ ਵਿਕਰੀ ਅਤੇ ਮਾਰਕੀਟ ਗੱਲਬਾਤ ਲਈ ਪੇਸ਼ੇਵਰ ਕਮਰੇ।",
    "cr_gallery_cap2": "ਏਜੰਟਾਂ, ਰਿਣਦਾਤਿਆਂ, ਅਤੇ ਵਿਕਾਸ-ਮੁਖੀ ਪੇਸ਼ੇਵਰਾਂ ਨਾਲ ਲਾਈਵ ਮੌਰਗੇਜ ਸਿਖਲਾਈ।",
    "cr_growth_room": "ਵਿਕਾਸ ਕਮਰਾ",
