    "cr_growth_kicker": "ਵਿਕਰੀ, ਸਿਖਲਾਈ ਅਤੇ ਵਿਕਾਸ",
    "cr_growth_h2": "ਇੱਕ ਟੀਮ ਵਿੱਚ ਸ਼ਾਮਲ ਹੋਵੋ ਜੋ ਲਗਨ ਵਿੱਚ ਨਿਵੇਸ਼ ਕਰਦੀ ਹੈ।",
    "cr_growth_lead": "RDC ਉਹਨਾਂ ਲੋਕਾਂ ਲਈ ਬਣਾਇਆ ਗਿਆ ਹੈ ਜੋ ਇੱਕ ਡੈਸਕ ਅਤੇ ਲਾਇਸੈਂਸ ਤੋਂ ਵੱਧ ਚਾਹੁੰਦੇ ਹਨ। ਸਾਡਾ ਮਾਹੌਲ ਏਜੰਟਾਂ ਨੂੰ ਪੇਸ਼ੇਵਰ ਕਮਰਿਆਂ, ਅਸਲ ਗੱਲਬਾਤ, ਰਿਣਦਾਤਾ ਸਿੱਖਿਆ, ਮਾਰਕੀਟ ਸੂਝ, ਅਤੇ ਵਿਕਰੀ ਗਤੀ ਵਿੱਚ ਲਿਆਉਂਦਾ ਹੈ।",
    "cr_gp1": "ਵਿਹਾਰਕ ਮੌਰਗੇਜ ਸਿਖਲਾਈ ਨਾਲ ਆਪਣੀ ਵਿਕਰੀ ਗੱਲਬਾਤ ਨੂੰ ਤਿੱਖਾ ਕਰੋ।",
