    "cr_how_p": "RDC ਉਹਨਾਂ ਮੌਰਗੇਜ ਪੇਸ਼ੇਵਰਾਂ ਲਈ ਬਣਾਇਆ ਗਿਆ ਹੈ ਜੋ ਉਸ ਸੁਤੰਤਰਤਾ ਨੂੰ ਗੁਆਏ ਬਿਨਾਂ ਢਾਂਚਾ ਚਾਹੁੰਦੇ ਹਨ ਜੋ ਕਮਿਸ਼ਨ-ਆਧਾਰਿਤ ਕੰਮ ਨੂੰ ਲਾਭਦਾਇਕ ਬਣਾਉਂਦੀ ਹੈ।",
