    "cr_p4_h3": "ਰਿਸ਼ਤਾ ਵਿਕਾਸ",
    "cr_p4_p": "ਗਾਹਕਾਂ, ਰੀਅਲਟਰਾਂ, ਬਿਲਡਰਾਂ, ਲੇਖਾਕਾਰਾਂ, ਵਪਾਰ ਮਾਲਕਾਂ, ਅਤੇ ਕਮਿਊਨਿਟੀ ਸੰਪਰਕਾਂ ਨਾਲ ਇੱਕ ਦੁਹਰਾਉਣਯੋਗ ਰੈਫਰਲ ਲੈਅ ਬਣਾਓ।",
