    "pc_note": "ਅਨੁਮਾਨ ਸਿਰਫ਼ ਉਦਾਹਰਨ ਲਈ ਹਨ। ਅੰਤਿਮ ਭੁਗਤਾਨ, ਬੀਮਾ, ਭੂਮੀ ਟ੍ਰਾਂਸਫਰ ਟੈਕਸ, ਦਰਾਂ, ਅਤੇ ਰਿਣਦਾਤਾ ਸ਼ਰਤਾਂ ਦੀ ਪੁਸ਼ਟੀ ਇੱਕ ਲਾਇਸੰਸਸ਼ੁਦਾ ਮੌਰਗੇਜ ਪੇਸ਼ੇਵਰ ਅਤੇ ਵਕੀਲ ਦੁਆਰਾ ਕੀਤੀ ਜਾਣੀ ਚਾਹੀਦੀ ਹੈ।",
