    "home_why_kicker": "为何选择 Royal Den Capital？",
    "home_why_title": "更多贷款机构，更优方案，为您的个案量身定制建议。",
    "home_why_desc": "25年多以来，Royal Den Capital 一直协助客户比较各贷款机构方案、获取具竞争力的利率，并制定切合实际生活的按揭策略。",
    "home_why_li1": "25年以上按揭及贷款经验",
    "home_why_li2": "对接庞大的贷款机构、银行及另类贷款网络",
