    "home_why_li4": "针对购房、续约、再融资及复杂个案的智能方案",
    "home_why_li5": "从最初咨询到最终放款，全程由同一支专责团队负责",
    "home_approval_rate": "审批通过率",
    "home_career_media_label": "销售与成长文化",
    "home_career_kicker": "加入RDC团队",
    "home_career_title": "在激发雄心的环境中，打造属于您的按揭事业。",
    "home_career_desc": "RDC 为积极进取的按揭从业人员提供一个专业的成长平台：学习专业知识、自信销售、建立转介关系，并与重视业绩的伙伴共同成长。",
    "home_career_point1": "实战销售培训",
    "home_career_point2": "市场与贷款机构洞察",
    "home_career_point3": "以成长为导向的团队文化",
    "home_explore_careers": "查看招聘机会",
    "home_ratetypes_kicker": "按揭利率类型",
    "home_ratetypes_title": "选择最适合您生活方式的利率。",
    "home_ratetypes_desc": "在固定利率与浮动利率之间选择稳定或灵活性，配合您的承受能力、财务目标及不断变化的市场状况。",
    "home_fixed_rate": "固定利率",
    "home_fixed_rate_desc": "还款稳定，预算可控",
    "home_variable_rate": "浮动利率",
    "home_variable_rate_desc": "若利率下降，可享更大灵活性",
    "home_ratetypes_footer": "不确定哪种方案适合您的计划？请前往我们的按揭方案页面查看完整的<a href=\"/full-service-mortgage-solution/#fixed-variable\" style=\"color:var(--rdc-gold);font-weight:800;\">固定利率与浮动利率比较</a>。",
    "home_faq_kicker": "常见问题",
    "home_faq_title": "按揭与融资常见问题",
    "home_faq_desc": "快速解答购房者与企业主最常问的问题。",
    "home_faq1_q": "我能负担多少按揭？",
    "home_faq1_a": "贷款机构通常参考两个比率：总债务偿还比率（GDS），即住房支出占收入的比例，上限通常约为39%；以及总负债偿还比率（TDS），即所有债务还款占收入的比例，上限通常约为44%。您的具体额度取决于收入、债务、信用状况以及按揭压力测试利率。",
    "home_faq2_q": "预先资格评估与预先批核有什么区别？",
    "home_faq2_a": "预先资格评估是根据您提供的数据快速做出的非正式估算。预先批核则是更全面的审核，贷款机构会核实您的收入、信用及债务情况，通常会将利率锁定60至120天，让您在选购房产时有一个更可靠的参考额度。",
    "home_faq3_q": "我需要多少首付？",
    "home_faq3_a": "在加拿大，购房价格首500,000加元部分的最低首付为5%，500,000至999,999加元部分为10%。购房价格达到100万加元或以上，首付至少需要20%。任何低于20%的首付都需要购买按揭违约保险。",
    "home_faq4_q": "什么是按揭压力测试？",
    "home_faq4_a": "受联邦监管的贷款机构必须以您的合同利率加2%，或加拿大银行的基准合格利率两者中较高者为标准来评估您的资格，即使您的实际利率较低。这项测试旨在确认即使利率上升，您仍有能力负担还款。",
    "home_faq5_q": "我需要多高的信用分数才能获批？",
    "home_faq5_a": "大多数传统贷款机构要求信用分数达到680分或以上才能获得最优利率。低于此分数，您仍有可能通过另类贷款机构或私人贷款机构获批，通常需要更高的首付或稍高的利率，我们可以协助您对接此类资源。",
    "home_faq6_q": "按揭经纪与银行有什么区别？",
    "home_faq6_a": "银行只能为您提供其自身的按揭产品。作为持牌按揭经纪，Royal Den Capital 会代表您比较各大银行、信用合作社、另类贷款机构及私人贷款机构的利率与条款，在大多数情况下您无需支付额外费用，因为我们的报酬由贷款机构支付。",
    "home_faq7_q": "自雇人士或加拿大新移民能否获批？",
    "home_faq7_a": "可以。自雇借款人可凭两年的报税记录及企业财务报表获批，或通过另类贷款机构的申报收入计划申请。信用记录有限的新移民也可通过专属的新移民按揭计划获批，首付最低可至5%-10%。",
    "home_faq8_q": "按揭审批需要多长时间？",
    "home_faq8_a": "在收齐相关文件后，预先批核通常可在24至48小时内完成。签署购房协议后，完成评估与核保的正式批核通常需要5至10个工作日，但较复杂的商业或企业个案可能需要更长时间。",
    "home_glossary_title": "在做出重大决定前，先了解简明术语。",
    "home_term1_a": "在您提出购房要约前，由贷款机构进行审核，帮助您了解自身的借贷能力。",
    "home_term2_a": "更换或调整现有按揭，以提取净值、合并债务或变更条款。",
    "home_term3_q": "另类贷款机构",
    "home_term3_a": "不受传统银行审批标准限制的贷款机构，通常适用于自雇人士、收入来源特殊或个案较复杂的申请人。",
    "home_cta_title": "真实的人。真切的帮助。真实的成效。",
    "home_cta_desc": "Royal Den 拥有一支专业团队，能在处理复杂融资细节的同时，协助您打造安稳而成功的未来。",
    "home_cta_btn": "即刻申请 - 成就未来",
