    "home_disclosures_title": "利率、条款及重要披露信息",
    "home_d1_q": "本网站显示的利率",
    "home_d1_a": "所示利率仅供参考，可能随时变动，恕不另行通知。除非经贷款机构书面确认，否则不构成担保利率或承诺。",
    "home_d2_q": "审批结果不作保证",
    "home_d2_a": "所有按揭申请仍须符合标准贷款审核条件，包括收入核实、信用审批及物业估值（视信用审批结果而定）。最终条款由贷款机构而非 Royal Den Capital 决定。",
    "home_d3_q": "计算器估算结果",
    "home_d3_a": "本网站计算器所得出的按揭还款、保险费及土地转让税等数字仅为示意性估算，未必反映您的实际费用。保险费及土地转让税由保险公司及省／市政府厘定，可能会有所变动。",
    "home_d4_q": "我们的收费方式",
    "home_d4_a": "作为持牌按揭经纪机构，Royal Den Capital 可能就促成的按揭业务从贷款机构获得报酬（介绍费或佣金）。这不会增加您的利率或费用，也不会影响我们所提供建议的公正性。",
    "home_d5_q": "牌照信息",
    "home_d5_a": "Royal Den Capital 依据按揭经纪牌照编号 M25002134 及 Mortgage Alliance 安大略省牌照编号 10530 运营。Royal Den Capital 为独立拥有及经营的公司。",
    "home_d6_q": "不构成财务、法律或税务建议",
    "home_d6_a": "本网站内容，包括术语表、常见问题及流程指南，仅供一般教育参考之用，不构成财务、法律或税务建议。在做出决定前，请就您的具体情况咨询持牌顾问。",
    "home_d7_q": "地区适用性",
    "home_d7_a": "本网站所提及的贷款机构、产品或计划并非在所有省份或适用于所有物业类型。具体是否适用取决于贷款机构及您的个人资格审核结果。",
    "home_d8_q": "错误与遗漏",
    "home_d8_a": "如有错误或遗漏，恕不负责（E&OE）。尽管我们努力确保本网站信息准确并保持最新，但所提及的利率、计划及数字仍可能变动；请在依赖任何信息前直接与我们联系确认。",
    "home_chat_button": "在线客服",
    "home_newsletter_desc": "订阅以获取 Royal Den Capital 提供的按揭贴士、利率更新及融资资讯。",
    "home_newsletter_name_ph": "姓名",
