    "gl_broker_p": "在安大略省，按揭经纪公司、经纪人、代理人及管理人员除获豁免外，均受金融服务监管局（FSRA）监管。持牌按揭专业人士可协助比较贷款机构方案、收集文件、解释条款及风险，并全程指导个案完成审批与成交。",
