    "gl_sources_kicker": "资料来源说明",
    "gl_sources_h2": "本指南的信息依据",
    "gl_sources_p": "本页面内容旨在为客户提供教育参考，并不构成法律、税务或贷款批核建议。相关规则、贷款机构政策、利率及审批标准均可能发生变化。在做出具有约束力的决定前，请务必就您的具体个案确认最终结果。",
