    "au_h1": "关于我们",
    "au_bc_home": "首页",
    "au_bc_about": "关于我们",
    "au_who_kicker": "Royal Den Capital - 关于我们团队",
    "au_who_h2": "我们不仅是服务提供者，更是您成长道路上的伙伴。",
    "au_goal_lead": "我们的目标：在每一步为您提供指导、讲解每一项方案，并代表您进行协商，为您争取市场上最具竞争力的利率与条款。",
    "au_who_p": "Royal Den Capital 是一支专注于按揭咨询的团队，秉承信任、专业与以客户为先的服务理念。我们与加拿大各地的主要银行、信用合作社、另类贷款机构及私人贷款机构合作，为每一种情况提供合适的融资方案，从简单的住宅购房到复杂的商业交易，皆能妥善应对。",
    "au_promise_strong": "我们对您的承诺：",
    "au_promise_rest": " 与 Royal Den Capital 合作，您获得的不仅仅是一份按揭，更是一位致力于您财务成长、保障与未来发展的伙伴。",
    "au_years_exp": "年行业经验",
    "au_how_kicker": "运作流程",
    "au_how_h2": "让置业之路化繁为简。",
    "au_step1_h3": "在线申请",
    "au_step1_p": "只需几分钟，即可完成我们快速安全的在线申请。告诉我们您的目标、物业及财务详情，我们将立即为您开始办理。",
    "au_step2_h3": "为您量身设计方案",
    "au_step2_p": "我们的按揭专家会审阅您的资料，比较各项方案并优化条款，为您量身设计符合需求的贷款方案。",
    "au_step3_h3": "获得资金",
    "au_step3_p": "获批后，我们会迅速完成所有文件手续并推进成交。资金到位后，您便离目标更近一步。",
    "au_getknow_kicker": "认识我们",
    "au_getknow_h2": "我们协助您构建的一切。",
    "au_sv1_h3": "企业贷款咨询",
    "au_sv1_p": "为工资发放、设备采购及业务扩张提供融资方案，并对接了解您所在行业的贷款机构。",
    "au_sv2_h3": "按揭与再融资",
    "au_sv2_p": "提供住宅及商业按揭咨询，从首次购房到再融资及续约，全程陪伴。",
    "au_sv3_h3": "投资与股权规划",
    "au_sv3_p": "对接股权合作伙伴及投资结构，助您在不放弃控制权的前提下实现增长。",
    "au_sv4_h3": "商业融资",
    "au_sv4_p": "为商业场所、创收物业、混合用途个案及扩张项目提供贷款方案。",
    "au_team_kicker": "管理团队",
    "au_team_h2": "从策略规划到核保审批，架构清晰的贷款服务团队。",
    "au_team_p": "Royal Den Capital 确保每个个案都有明确分工、清晰的升级处理流程，并从申请到放款全程提供支持。",
