    "au_uw_p": "负责审核文件、核实贷款机构条件、整理提交材料，并协助让每个个案在批核前更加完善。",
    "au_licenseno_pb": "许可证编号：M25002134",
    "au_license_tbc": "许可证编号待定",
    "au_why_kicker": "为何选择 Royal Den Capital？",
    "au_why_h2": "25年以上的按揭实力、贷款机构资源，以及以客户为先的专业建议。",
    "au_why_p": "Royal Den Capital 专为期望获得不仅仅是快速报价的客户而设。我们结合丰富经验、贷款机构关系、精准的利率比较及切实可行的建议，助您满怀信心地稳步前行。",
    "au_w1_h3": "25年以上行业经验",
    "au_w1_p": "无论个案简单与否，经验都至关重要，个案越复杂，经验的价值就越发凸显。我们的团队拥有25年以上的市场经验，助客户免于盲目猜测，以清晰的思路完成融资流程。",
    "au_w1_li1": "凭借真实的市场周期经验提供建议，而非千篇一律的话术。",
    "au_w1_li2": "针对购房、续约、再融资及复杂个案提供切实可行的建议。",
    "au_w2_h3": "对接更多贷款机构",
    "au_w2_p": "单一贷款机构只能提供一种选择。Royal Den Capital 让客户接触到更广泛的银行、信用合作社、单一渠道贷款机构、另类贷款机构及私人贷款方案网络，让个案有更多可行途径。",
    "au_w2_li1": "更多贷款机构途径，意味着更多机会匹配客户的真实情况。",
    "au_w2_li2": "无论是资质优良的个案，还是需要创意结构设计的个案，都同样适用。",
    "au_w3_h3": "更专业的利率比较",
    "au_w3_p": "我们会结合您的完整情况比较各贷款机构方案，而非只看屏幕上最低的数字。目标是争取优惠利率、公平条款、可负担的还款额，且细则中没有任何隐藏惊喜。",
    "au_w3_li1": "利率比较会一并考量违约金、还款权益、费用及灵活性。",
    "au_w3_li2": "客户在做出承诺前，就能清楚看到各方案的利弊权衡。",
    "au_w4_h3": "为您量身定制的建议",
    "au_w4_p": "您并非只是又一份申请材料。我们会倾听您的故事、时间安排、收入、物业情况及长期目标，进而为您量身打造真正契合您生活与工作方式的按揭策略。",
    "au_w4_li1": "每一项建议都从客户的目标及承受能力出发。",
    "au_w4_li2": "我们以简明易懂的语言讲解方案，而非贷款机构的专业术语。",
    "au_w5_h3": "复杂个案解决方案",
    "au_w5_p": "自雇收入、信用问题、投资物业、建筑工程、商业融资、再融资或债务合并，都需要精明的结构设计。我们深知如何合理定位个案，找到合适的贷款途径。",
    "au_w5_li1": "为非标准收入及特殊物业情况提供有力支持。",
    "au_w5_li2": "在个案进入核保环节前，先做好清晰的定位。",
    "au_w6_h3": "一站式满足各类按揭需求",
    "au_w6_p": "购房、续约、再融资、HELOC、净值提取、装修融资、新移民计划、反向按揭及商业按揭，均可由同一支专责团队在同一平台上妥善处理。",
    "au_w6_li1": "按揭规划、贷款机构比较及后续步骤建议，一站式满足。",
    "au_w6_li2": "减少沟通混乱及交接环节，带来更清晰顺畅的客户体验。",
    "au_cta_h2": "准备好满怀信心地实现增长了吗？",
    "au_cta_p": "在 Royal Den Capital，我们全程陪伴您的每一步。体验拥有一支真诚关怀、并具备实现真实成效专业能力的团队，究竟意味着什么。",
