    "au_card_p": "无论您是购房、投资、再融资还是开发项目，我们都在这里以清晰的思路和坚定的信心为您提供指导。",
    "au_mission_strong": "我们的使命：",
    "au_mission_rest": " 以智慧的按揭策略赋能加拿大人，一处物业接一处物业地，构建稳定、财富与长期的成功。",
    "au_phone_prefix": "电话：905-609-1818",
    "cr_kicker": "Royal Den Capital 招聘信息",
    "cr_h1": "与我们一同开创您的按揭事业。",
    "cr_lead": "我们正在寻找积极进取的按揭专业人士，希望获得更多贷款机构资源、更有力的支持，以及一份具备成长空间的佣金制工作机会。",
    "cr_fact1": "Oakville办公室",
    "cr_fact2": "佣金制",
    "cr_fact3": "更多贷款机构资源",
    "cr_apply_now": "立即申请",
    "cr_view_role": "查看职位",
    "cr_who_h2": "什么样的人适合加入？",
    "cr_who_li1": "持牌或有志成为按揭经纪代理的人士。",
    "cr_who_li2": "具备自我驱动力、擅长建立人脉关系的人士。",
    "cr_who_li3": "追求佣金上升空间，而非固定薪资路径的专业人士。",
    "cr_who_li4": "重视结构支持、贷款机构资源及个案支持的经纪代理。",
    "cr_why_kicker": "为何加入RDC",
    "cr_why_h2": "专为成交高手打造的经纪环境。",
    "cr_why_p": "我们坚守简单的承诺：清晰的支持、扎实的贷款机构资源、切实的指导，以及一支希望每个个案都得到妥善处理的团队。",
    "cr_b1_h3": "更多贷款机构途径",
    "cr_b1_p": "并非所有客户都适用同一套方案。您将对接更广泛的贷款网络，让购房、再融资、续约、净值提取及复杂个案都拥有更多可行途径。",
    "cr_b2_h3": "佣金制收入潜力",
    "cr_b2_p": "这是一份佣金制工作机会，适合希望收入与业绩、关系建立及客户服务直接挂钩的人士。",
    "cr_b3_h3": "经验丰富的领导团队指导",
    "cr_b3_p": "品牌背后拥有25年以上的按揭及贷款经验，经纪代理可从中学习如何构建个案结构、提出更精准的问题，并避免常见的审批失误。",
    "cr_b4_h3": "扎根Oakville的团队",
    "cr_b4_p": "Royal Den Capital 立足Oakville运营，为经纪代理提供一个专业的协作、客户沟通及个案支持基地。",
    "cr_gallery_cap1": "专业的会议空间，用于严肃的销售及市场探讨。",
    "cr_gallery_cap2": "与经纪代理、贷款机构及具成长意识的专业人士开展的实战按揭培训。",
    "cr_growth_room": "成长空间",
    "cr_growth_tagline": "培训。销售。人脉。",
    "cr_growth_kicker": "销售、培训与成长",
    "cr_growth_h2": "加入一支投资于雄心壮志的团队。",
    "cr_growth_lead": "RDC 专为不满足于仅拥有一张办公桌和一纸牌照的人士而设。我们的环境让经纪代理置身于专业的会议空间、真实的交流、贷款机构知识培训、市场洞察，以及销售动能之中。",
    "cr_gp1": "通过实战按揭培训，磨练您的销售沟通技巧。",
    "cr_gp2": "与真正专注于成长的人建立人脉关系。",
    "cr_gp3": "学习如何将客户的疑问转化为更扎实的个案及更有效的跟进。",
    "cr_growth_btn": "开启您的职业对话",
    "cr_how_kicker": "我们的工作方式",
    "cr_how_h2": "在最关键之处提供支持。",
    "cr_how_p": "RDC 专为希望获得结构支持、同时不失佣金制工作独立性的按揭专业人士而设。",
    "cr_p1_h3": "客户接待",
    "cr_p1_p": "在选择贷款机构途径前，及早提出正确的问题、收集完整清晰的文件，并了解客户的目标。",
    "cr_p2_h3": "个案结构设计",
    "cr_p2_p": "了解收入、信用、物业类型、净值及时机等因素，如何影响银行、另类贷款及私人贷款方案的审批结果。",
    "cr_p3_h3": "贷款机构定位",
    "cr_p3_p": "比较各项方案、准备更具说服力的申请材料，并以清晰的方式沟通，让客户理解整体方案及各项利弊权衡。",
    "cr_p4_h3": "人脉关系拓展",
    "cr_p4_p": "与客户、地产经纪、建筑商、会计师、企业主及社区人脉建立可持续的转介机制。",
    "cr_role_kicker": "招聘职位",
    "cr_role_h2": "按揭代理／经纪",
    "cr_role_p": "此机会最适合能够适应佣金制工作、主动开发客户，并秉持以客户为先理念的人士。",
