    "cr_wo_li4": "随着经验积累，逐步接触商业及建筑融资机会。",
    "cr_std_kicker": "RDC标准",
    "cr_std_h2": "独立工作，专业标准。",
    "cr_std_p": "佣金制按揭工作看重主动性。我们寻找的是能够坚持到底、维护客户信任，并悉心推进个案的专业人士。",
    "cr_s1_h3": "主动跟进，负责到底",
