    "cr_s2_h3": "谨慎对待每一份个案",
    "cr_s2_p": "按揭建议涉及客户的私人财务细节。我们期望团队成员妥善处理相关文件、笔记、贷款机构条件及客户沟通内容。",
    "cr_s3_h3": "开拓您的市场",
    "cr_s3_p": "表现最出色的经纪代理，往往善于通过人脉拓展、转介、本地影响力及持续的客户教育来创造机会。",
